/* Rendu */
const status=()=>{const head=S.commits.at(-1)?.tree||{},cur={},ch=[];for(const p in S.files)if(!/(^|\/)(node_modules|\.git)\//.test(p))cur[p]=hf(S.files[p]);for(const p in cur)if(!(p in head))ch.push([p,'A']);else if(head[p]!==cur[p])ch.push([p,'M']);for(const p in head)if(!(p in cur))ch.push([p,'D']);return{cur,ch}};
const nodeHtmlOld=(n,base,d)=>{let h='';const pad=`style="padding-left:${8+d*14}px"`;for(const k of Object.keys(n.d).sort()){const p=base+k,c=S.collapsed.includes(p);h+=`<div class="row" ${pad}><span data-a="${sel?'pkd':'tog'}" data-v="${esc(p)}">${sel?(isDirSel(p)?'☑ ':'☐ '):''}${c?'▸':'▾'} ${esc(k)}</span><button class="m" data-a="md" data-v="${esc(p)}">⋯</button></div>`;if(!c)h+=nodeHtml(n.d[k],p+'/',d+1)}for(const p of n.f)h+=`<div class="row${p===S.open?' sel':''}" ${pad}><span data-a="${sel?'pk':'open'}" data-v="${esc(p)}">${sel?(sel.has(p)?'☑ ':'☐ '):''}<i class="dt" style="background:${col(p)}"></i>${esc(p.split('/').pop())}</span><button class="m" data-a="mf" data-v="${esc(p)}">⋯</button></div>`;return h};
const rFold=()=>{const root={d:{},f:[]};for(const p of Object.keys(S.files).sort()){let n=root;const ps=p.split('/');for(const k of ps.slice(0,-1))n=n.d[k]??={d:{},f:[]};n.f.push(p)}
$('#p-f').innerHTML=`<div class="grid"><button data-a="nf">Nouveau fichier</button><button data-a="nd">Nouveau dossier</button><button data-a="up">Importer des fichiers</button><button data-a="zi">Importer un ZIP</button><button data-a="ze">Exporter en ZIP</button><button data-a="sm">Sélectionner</button></div>`+(Object.keys(S.files).length?nodeHtml(root,'',0):'<p class="mu">Aucun fichier. Crée un fichier ou importe un ZIP pour commencer.</p>')};
const rS=()=>{$('#p-s').innerHTML=`<input id="q" placeholder="Rechercher dans tous les fichiers"><input id="r" placeholder="Remplacer par"><button data-a="rep">Tout remplacer</button><div id="sres"></div>`};
