const rHold=()=>{$('#p-h').innerHTML=`<p class="mu">Crée un token « fine-grained » (GitHub, Settings, Developer settings). Choisis « Only select repositories » et ton dépôt. Permissions : Contents en lecture et écriture, Metadata en lecture.</p><input id="tk" type="password" placeholder="Token GitHub" value="${esc(S.cfg.token)}"><input id="rp" placeholder="URL du dépôt ou propriétaire/dépôt" value="${esc(S.cfg.repo)}"><input id="br" placeholder="Branche" value="${esc(S.cfg.branch)}"><div class="grid"><button class="wide pr" data-a="tst">Tester le token</button><button data-a="pull">Pull</button><button data-a="push">Push</button></div><pre id="ghs" class="mu"></pre>`};
const render=()=>{{const pn=S.index.find(i=>i.id===S.cur)?.name||'CodePocket';$('#title').dataset.a='pjs';$('#title').innerHTML=`<div style="display:flex;align-items:center;min-width:0"><b style="min-width:0">${esc(pn)}</b>${ic('chev').replace('<svg ','<svg style="width:14px;height:14px;transform:rotate(90deg);margin-left:6px;color:var(--ac)" ')}</div><small>${esc(S.open?S.open.split('/').pop():'Aucun fichier ouvert')}</small>`;$('[data-a=prev]').style.display=/\.html?$/i.test(S.open||'')?'':'none'}rTabs();document.querySelectorAll('#rail button').forEach(b=>b.classList.toggle('on',b.dataset.v===S.tab));document.querySelectorAll('.pane').forEach(p=>p.classList.toggle('on',p.id==='p-'+S.tab));({f:rF2,g:rG,h:rH,s:rS,c:rC,t:rT,a:rA})[S.tab]();bar()};
