aiSend:async v=>{if(!S.ai.on)return;if(!S.ai.key){toast('Ajoute ta clé Gemini dans Paramètres');return A.tab('c')}const el=$('#ai-in'),t=(typeof v==='string'&&v)?v:(el?.value||'').trim();if(!t)return;if(el)el.value='';S.ai.msgs.push({r:'u',t},{r:'m',t:'…',w:1});rA();try{const a=await aiCall();S.ai.msgs.pop();S.ai.msgs.push({r:'m',t:a})}catch(e){S.ai.msgs.pop();S.ai.msgs.push({r:'m',t:aiNice(e),err:1})}S.ai.msgs=S.ai.msgs.slice(-30);rA();save()},back:()=>$('#home').classList.remove('on'),
op:v=>openProj(v),st:()=>{$('#home').classList.remove('on');A.tab('c')},tm:()=>{$('#home').classList.remove('on');A.tab('t')},
