cl:async()=>{if(!S.cfg.token){const t=await ask('Token GitHub (reste sur ce téléphone)','');if(!t)return;S.cfg.token=t}const u=await ask('URL du dépôt GitHub','https://github.com/');if(!u)return;const m=u.match(/([\w.-]+)\/([\w.-]+?)(?:\.git)?\/?$/);if(!m)return toast('URL invalide');await newProj(m[2],'clone');S.cfg.repo=u;try{S.cfg.branch=(await gh(repoPath())).default_branch}catch(e){return toast(nice(e))}persist();await A.pull()},
