sync:async()=>{if(!S.cfg.token||!S.cfg.repo){toast('Ajoute ton token et ton dépôt dans GitHub');return A.tab('h')}if(!S.cur)return A.home();if(!await safe())return;const n=status().ch.length;if(n)doCommit('Mise à jour depuis CodePocket ('+n+' fichier'+(n>1?'s':'')+')');save();bar();await A.push()},
pal:()=>{const cmds=[...(S.ai.on?[['Demander à Gemini',()=>A.tab('a')]]:[]),['Accueil',()=>A.home()],['Terminal',()=>A.tab('t')],['Envoyer sur GitHub (commit + push)',()=>A.sync()],['Pull depuis GitHub',()=>A.pull()],['Nouveau fichier',()=>A.nf()],['Importer un ZIP',()=>A.zi()],['Exporter en ZIP',()=>A.ze()],['Aperçu HTML',()=>A.prev()],['Rechercher dans les fichiers',()=>A.tab('s')],['Git',()=>A.tab('g')],['Paramètres',()=>A.tab('c')]];const all=[...cmds,...Object.keys(S.files).filter(p=>S.files[p].t!==undefined).sort().map(p=>[p,()=>openFile(p)])];let pl=[];const m=M();m.innerHTML='<div class="box"><input id="pq" placeholder="Fichier ou commande" autocomplete="off"><div id="pl"></div></div>';m.classList.add('on');const draw=()=>{const q=$('#pq').value.toLowerCase();pl=all.filter(x=>x[0].toLowerCase().includes(q)).slice(0,40);$('#pl').innerHTML=pl.map((x,i)=>`<div class="row" data-n="${i}"><span>${esc(x[0])}</span></div>`).join('')};draw();$('#pq').oninput=draw;$('#pq').focus();m.onclick=e=>{if(e.target===m)return m.classList.remove('on');const r=e.target.closest('[data-n]');if(r){m.classList.remove('on');pl[r.dataset.n][1]()}}},
