pull:async()=>{try{if(Object.keys(S.files).length&&!await ask('Remplacer les fichiers locaux par ceux de GitHub ?',null,'Pull'))return;log('Téléchargement…');const R=repoPath(),ref=await gh(`${R}/git/ref/heads/${S.cfg.branch}`),c=await gh(`${R}/git/commits/${ref.object.sha}`),t=c.tree.sha===EMPTY?{tree:[]}:await gh(`${R}/git/trees/${c.tree.sha}?recursive=1`),its=t.tree.filter(x=>x.type==='blob'),fs={};let n=0;await pool(its,6,async it=>{const b=await gh(`${R}/git/blobs/${it.sha}`);fs[it.path]=bytesToFile(Uint8Array.from(atob(b.content.replace(/\n/g,'')),ch=>ch.charCodeAt(0)));if(++n%10===0)log(`Téléchargement ${n}/${its.length}…`)});S.files=fs;S.base=ref.object.sha;S.tabs=[];closeEd();doCommit('Pull depuis GitHub');S.pushed={...S.commits.at(-1).tree};refresh();log(its.length+' fichiers récupérés.'+(t.truncated?' Attention : dépôt trop gros, liste tronquée.':''))}catch(e){log(nice(e))}}
