cl:async()=>{if(!S.cfg.token){const t=await ask('Token GitHub (reste sur ce téléphone)','');if(!t)return;S.cfg.token=t.trim()}REPOS=null;const r=await pickRepo();if(!r)return;await newProj(r.n.split('/')[1],'clone');S.cfg.repo=r.u;S.cfg.branch=r.b||'main';if(!r.b){try{S.cfg.branch=(await gh(repoPath())).default_branch}catch(e){return toast(nice(e))}}persist();await A.pull()},
